<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Database;use App\Services\AutomaticJudgeBrowserService;Auth::requireAdmin();$pdo=Database::connection();$roundId=(int)($_GET['round_id']??0);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');try{$r=$pdo->prepare("SELECT id,round_type,yes_count FROM bdc_scoring_rounds WHERE id=:r AND scoring_mode='automated'");$r->execute(['r'=>$roundId]);$round=$r->fetch();if(!$round)throw new RuntimeException('Round not found.');$judges=AutomaticJudgeBrowserService::progress($pdo,$roundId);$j=$pdo->prepare('SELECT id,judge_name,judge_order,is_chief,scoring_scope FROM bdc_scoring_judges WHERE round_id=:r ORDER BY judge_order');$j->execute(['r'=>$roundId]);$judgeRows=$j->fetchAll();$entries=[];if($round['round_type']==='final'){$q=$pdo->prepare("SELECT fp.id pair_id,fp.pair_number,le.display_name leader_name,fe.display_name follower_name FROM bdc_scoring_final_pairs fp JOIN bdc_scoring_entries le ON le.id=fp.leader_entry_id LEFT JOIN bdc_scoring_entries fe ON fe.id=fp.follower_entry_id WHERE fp.round_id=:r AND fp.pairing_status='confirmed' ORDER BY fp.pair_number");$q->execute(['r'=>$roundId]);foreach($q->fetchAll() as $x){$m=$pdo->prepare('SELECT judge_id,rank_value FROM bdc_scoring_final_marks WHERE round_id=:r AND pair_id=:p');$m->execute(['r'=>$roundId,'p'=>$x['pair_id']]);$marks=[];foreach($m->fetchAll() as $z)$marks[(int)$z['judge_id']]=(int)$z['rank_value'];$x['marks']=$marks;$x['score']=null;$entries[]=$x;}}else{$q=$pdo->prepare("SELECT id,bib_number,display_name,dance_role FROM bdc_scoring_entries WHERE round_id=:r AND entry_status='active' ORDER BY dance_role,bib_number");$q->execute(['r'=>$roundId]);foreach($q->fetchAll() as $x){$m=$pdo->prepare("SELECT judge_id,mark_type,alt_rank,weighted_score FROM bdc_scoring_marks WHERE round_id=:r AND entry_id=:e");$m->execute(['r'=>$roundId,'e'=>$x['id']]);$marks=[];$score=0.0;foreach($m->fetchAll() as $z){$v=$z['mark_type']==='yes'?'YES':($z['mark_type']==='alt'?'A'.(int)$z['alt_rank']:'—');$marks[(int)$z['judge_id']]=$v;$score+=(float)$z['weighted_score'];}$x['marks']=$marks;$x['score']=$score;$entries[]=$x;}}echo json_encode(['ok'=>true,'round_type'=>$round['round_type'],'judges'=>$judges,'judge_columns'=>$judgeRows,'entries'=>$entries,'server_time'=>microtime(true)],JSON_UNESCAPED_SLASHES);}catch(Throwable $e){http_response_code(422);echo json_encode(['ok'=>false,'error'=>$e->getMessage()]);}
